        internal sealed class MissionCounterBinderIdTieBreakComparer : IComparer<IReadOnlyMissionCounterBinder>
        {
            private readonly IComparer<IReadOnlyMissionCounterBinder> _inner;
            public MissionCounterBinderIdTieBreakComparer(IComparer<IReadOnlyMissionCounterBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyMissionCounterBinder? a, IReadOnlyMissionCounterBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<MissionCounterId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
